head.script:
// 로드시간 측정을 위한 로그
console.log(`페이지 로딩 시작: ${performance.now().toFixed(2)}ms`);


scwin.updateCanvasBackground = function () {
    if (!scwin.isWhiteboardActive) return;

    const screenSharePeer = Array.from(scwin.remotePeers.values()).find(p => p.isScreenShare);
    const isScreenShareActive = scwin.localScreenShareElement || screenSharePeer;

    // isCanvasOverlayActive 플래그를 여기서 업데이트 해주는 것이 좋습니다.
    scwin.isCanvasOverlayActive = !!isScreenShareActive;

    scwin.canvasLayer.classList.toggle('standalone', !isScreenShareActive);
};

scwin.popup_closeAction = function (argRuntimeID, argJsnInfo) {
    // argRuntimeID : 팝업의 실행 시점 아이디
    // argJsnInfo : 팝업의 부가 정보를 담은 JSON 객체
    // argJsnInfo.isCloseButtonClick : [true, false] 팝업의 닫기 버튼을 클릭해서 호출되었는지의 여부

    //팝업객체 접근
    var popObj = $p.getPopupWindow(argRuntimeID);
    scwin.roomClient.sendPeerStatus(popObj.scwin.time);

    return true; //팝업 닫기 (반환 값이 true인 경우만 팝업이 닫힘)
};

scwin.throttle = function (callback, delay) {
    let lastCall = 0;
    return function () {
        const now = new Date().getTime();
        if (now - lastCall >= delay) {
            lastCall = now;
            callback();
        }
    };
}

scwin.centerPopup = function (popupId, offsetY = 0) {
    const pop = $p.getPopup(popupId);
    if (pop) {
        const width = pop.popupWin.getSize("width");
        const height = pop.popupWin.getSize("height");
        const left1 = (top.window.innerWidth - width) / 2;
        const top1 = (top.window.innerHeight - height) / 2 + offsetY;
        pop.popupWin.setPosition(left1, top1);
    }
};

scwin.createPopUp = function (_id, _name, _jsnData, url, _popupWidth, _popupHeight) {
    if (_id === "adfPopUp" && $p.getPopup("drowsinessPopUp")) return;
    if (_id === "drowsinessPopUp" && $p.getPopup("adfPopUp")) return;

    if ($p.getPopup(_id)) {
        console.log(`Popup with ID '${_id}' already exists. Skipping creation.`);
        return;
    }
    var popupWidth = _popupWidth;
    var popupHeight = _popupHeight;
    var topPosition = (window.innerHeight - popupHeight) / 2;
    var leftPosition = (window.innerWidth - popupWidth) / 2;
    var options = {
        id: _id,
        type: "wframePopup",
        width: popupWidth + "px",
        height: popupHeight + "px",
        top: topPosition + "px",
        left: leftPosition + "px",
        popupName: _name,
        modal: true,
        closeAction: "scwin.popup_closeAction",
        dataObject: _jsnData
    };
    $p.openPopup(url, options);
}

scwin.checkAppReady = function () {
    return new Promise(resolve => {
        const interval = setInterval(() => {
            if (window.App && window.App.UIManager && window.App.RoomClient) {
                clearInterval(interval);
                resolve();
            }
        }, 50);
    });
};

scwin.updateVideoLayout = function () {
    const mainStageElements = [];
    const sidebarElements = [];

    // 해결: screenShareElement를 사용하는 코드보다 먼저 선언합니다.
    const screenSharePeer = Array.from(scwin.remotePeers.values()).find(p => p.isScreenShare);
    const screenShareElement = scwin.localScreenShareElement || screenSharePeer?.screenShareElement;

    let mainElement = null;

    if (screenShareElement) {
        mainElement = screenShareElement;
    } else if (scwin.pinnedProducerId) {
        const pinnedPeer = Array.from(scwin.remotePeers.values()).find(p => p.videoProducerId === scwin.pinnedProducerId);
        if (pinnedPeer) mainElement = pinnedPeer.elementWrapper;
    } else {
        // 원격 사용자 중 첫 번째 사용자를 메인으로 (화면 공유가 아닐 때)
        const firstRemoteVideo = Array.from(scwin.remotePeers.values())
            .filter(p => p.elementWrapper && !p.isScreenShare)[0];


        if (firstRemoteVideo) {
            mainElement = firstRemoteVideo.elementWrapper;
        } else if (scwin.myPeerId) {
            const myPeer = scwin.remotePeers.get(scwin.myPeerId);
            if (myPeer) mainElement = myPeer.elementWrapper;
        }
    }

    // 메인 요소가 결정되면 mainStageElements에 추가
    if (mainElement) {
        mainStageElements.push(mainElement);
    }

    // 2. 모든 peer(로컬 포함)를 순회하며 사이드바 요소 결정
    Array.from(scwin.remotePeers.values()).forEach(peer => {
        // 메인에 있지 않은 모든 비디오/로컬 래퍼를 사이드바로 보냄
        if (peer.elementWrapper && peer.elementWrapper !== mainElement) {
            sidebarElements.push(peer.elementWrapper);
        }
    });

    // 3. 칠판 관련 로직
    mainStageElements.push(scwin.canvasLayer);
    if (scwin.isWhiteboardActive && !scwin.isCanvasOverlayActive) {
        // 칠판 단독 모드일 때 메인에 있는 다른 요소들을 사이드바로 이동
        const elementsToMove = mainStageElements.filter(el => el !== scwin.canvasLayer);
        sidebarElements.push(...elementsToMove);
        mainStageElements.splice(0, mainStageElements.length, scwin.canvasLayer);
    }

    // 4. UIManager에 최종 목록 전달
    scwin.uiManager.updateVideoLayout(mainStageElements, sidebarElements);
};

scwin.onpageload = async function () {
    // 모듈 상태 추적 변수들
    // scwin.isMicMuted = false;
    // scwin.isCameraOff = false;
    scwin.isMicMuted = meetingSettings.get("audioEnabled");
    scwin.isCameraOff = meetingSettings.get("videoEnabled");

    scwin.openModules = {}; // UI 모듈들 상태 추적

    top.window.onresize = scwin.throttle(function () {
        scwin.centerPopup("drowsinessPopUp", 0);
        scwin.centerPopup("adfPopUp", 50);
        scwin.centerPopup("checkIn", 50);
        scwin.centerPopup("checkout", 50);
    }, 200);

    await scwin.checkAppReady();
    console.log("Application classes are loaded. Application starting...");
    const { UIManager, RoomClient, loadModule } = window.App;
    scwin.loadModule = loadModule;
    scwin.uiManager = new UIManager();

    scwin.roomClient = new RoomClient(scwin.uiManager);

    let aiModule = null;
    scwin.canvasModule = null;
    let wsInstance = null;
    let chatModule = null;

    scwin.pinnedProducerId = null;
    scwin.localScreenShareElement = null;
    scwin.remotePeers = new Map();
    scwin.myPeerId = null; // 자신의 ID를 저장할 변수

    let isAudioEnabled = true;
    let isVideoEnabled = true; // isVideoEnabled는 RoomClient에서 관리되므로, 여기서는 초기 상태만 설정
    scwin.isScreenSharing = false;
    scwin.isWhiteboardActive = false;
    scwin.isCanvasOverlayActive = false;
    scwin.isAdmin = false;

    scwin.userHasAiModule = false;
    scwin.userHasCanvasModule = false;
    scwin.userHasScreenShareModule = false;
    scwin.userHasChatModule = false;

    const CANVAS_WEBSOCKET_URL = 'wss://' + location.host + '/InsWebApp/signal.do';
    const CANVAS_WORKER_URL = '/InsWebApp/js/canvas/canvas-worker.js';
    const MEDIA_PIPE_WORKER_URL = '/InsWebApp/media/dist/mediapipe.worker.bundle.js';

    const mainStage = scwin.uiManager.getMainStageContainer();
    // 메인 스테이지 참조를 WebSquare ID로 변경
    //const mainStage = document.getElementById('mf_grp_video_area');

    // 1. 칠판 레이어(canvasLayer)를 생성하고 모든 레이어 스타일을 적용
    scwin.canvasLayer = document.createElement("div");
    scwin.canvasLayer.id = "canvasLayer";
    scwin.canvasLayer.className = "main-stage-layer canvas-layer";
    scwin.canvasLayer.style.display = 'none';
    scwin.canvasLayer.style.position = 'absolute';
    scwin.canvasLayer.style.top = '0';
    scwin.canvasLayer.style.left = '0';
    scwin.canvasLayer.style.width = '100%';
    scwin.canvasLayer.style.height = '100%';
    scwin.canvasLayer.style.zIndex = '10';
    scwin.canvasLayer.style.overflow = 'hidden';

    // 2. CanvasModule이 사용할 내부 컨테이너를 별도로 생성
    const canvasModuleContainer = document.createElement("div");
    canvasModuleContainer.style.width = "100%";
    canvasModuleContainer.style.height = "100%";
    scwin.canvasLayer.appendChild(canvasModuleContainer); // 칠판 레이어 안에 추가
    mainStage.appendChild(scwin.canvasLayer);

    try {
        let CanvasModule = await scwin.loadModule("/InsWebApp/media/dist/modules/canvas.bundle.js", "CanvasModule");
        if (CanvasModule && !CanvasModule.prototype) {
            CanvasModule = CanvasModule.CanvasModule || CanvasModule.default;
        }
        // 해결: 새로 만든 내부 컨테이너를 전달합니다.
        scwin.canvasModule = new CanvasModule(canvasModuleContainer, CANVAS_WEBSOCKET_URL, CANVAS_WORKER_URL);
    } catch (e) {
        console.error("초기 CanvasModule 로드 실패:", e);
    }

    scwin.roomClient.on("connected", (ws) => {
        wsInstance = ws;
        if (scwin.userHasCanvasModule) {
            // UIManager 화이트보드 버튼이 존재할 때만 표시
            if (scwin.uiManager && scwin.uiManager.showWhiteboardButton) {
                scwin.uiManager.showWhiteboardButton();
            }
        }

        var jsnPopupData = {
            "type": "json",
            "name": "popup_param",
            "data": {
                "name": meetingSettings.get("participantName")
            } // 실제 전달할 데이터
        };

        scwin.createPopUp("checkIn", " ", jsnPopupData, "/InsWebApp/main/attendance_confirmation_pop_up.xml", 400, 350);
        //입장시 출석 완료

        if (scwin.userHasChatModule) {
            // 채팅 기능은 모듈 버튼 시스템으로 처리됨
            console.log("채팅 기능은 모듈 버튼으로 제공됩니다.");
        }

        // 모든 사용자에게 개인 대시보드 초기화 (관리자 여부와 상관없이)
        if (window.PersonalDashboardController) {
            setTimeout(() => {
                const currentUserId = scwin.myPeerId || roomClient.peerId || 'local-user';
                window.PersonalDashboardController.init(currentUserId);
                console.log('[Personal Dashboard] 개인 대시보드 사전 초기화:', currentUserId);
            }, 2000); // 시간을 늘려서 peerId 설정을 기다림
        }

        // AI 모니터링 통계를 위한 WebSocket 메시지 가로채기
        const originalSend = ws.send;
        ws.send = function (data) {
            try {
                const message = JSON.parse(data);
                // peerStatusUpdated 이벤트를 감지하여 통계 업데이트
                if (message.action === 'peerStatusUpdated' && message.data) {
                    const { peerId, status } = message.data;
                    if (peerId && status && window.aiMonitoringStats) {
                        window.aiMonitoringStats.updateParticipantStatus(peerId, status);
                        console.log('[AI Stats] 로컬 상태 업데이트:', peerId, status);
                    }
                }
            } catch (e) {
                // JSON 파싱 실패 시 무시
            }
            return originalSend.call(this, data);
        };

        // WebSocket 수신 메시지도 가로채기 (다른 참여자들의 상태 업데이트)
        ws.addEventListener('message', function (event) {
            try {
                const message = JSON.parse(event.data);
                if (message.action === 'peerStatusUpdated' && message.data) {
                    const { peerId, status } = message.data;
                    if (peerId && status && window.aiMonitoringStats) {
                        // 참여자 이름을 remotePeers에서 찾거나 기본값 사용
                        let peerName = `참여자_${peerId.slice(-4)}`;
                        if (scwin.remotePeers && scwin.remotePeers.has(peerId)) {
                            // 실제 참여자 정보가 있다면 더 나은 이름 사용
                            peerName = `참여자_${peerId.slice(-4)}`;
                        }

                        window.aiMonitoringStats.initializeParticipant(peerId, peerName);
                        window.aiMonitoringStats.updateParticipantStatus(peerId, status);
                        console.log('[AI Stats] 원격 상태 업데이트:', peerId, status);
                    }
                }
            } catch (e) {
                // JSON 파싱 실패 시 무시
            }
        });
    });

    scwin.roomClient.on("canvas", (data) => {
        if (data.type === "activate") {
            scwin.isWhiteboardActive = true;
            scwin.canvasLayer.style.display = 'block';

            // 화이트보드 버튼 상태 업데이트
            scwin.updateModuleButtonState('WHITEBOARD', true, {
                activeText: '칠판 사용중',
                inactiveText: '칠판',
                activeColor: '#27ae60',
                inactiveColor: '#667eea'
            });

            //scwin.uiManager.whiteboardButton.textContent = "칠판 끄기";
        } else if (data.type === "deactivate") {
            scwin.isWhiteboardActive = false;
            scwin.canvasLayer.style.display = 'none';

            // 화이트보드 버튼 상태 업데이트
            scwin.updateModuleButtonState('WHITEBOARD', false, {
                activeText: '칠판 사용중',
                inactiveText: '칠판',
                activeColor: '#27ae60',
                inactiveColor: '#667eea'
            });

            //scwin.uiManager.whiteboardButton.textContent = "칠판";
        } else if (scwin.canvasModule) {
            scwin.canvasModule.signal(data);
        }
        // 칠판이 켜지거나 꺼질 때마다 배경 상태와 비디오 레이아웃을 업데이트합니다.
        // 순서 변경: 배경 상태를 먼저 업데이트
        scwin.updateCanvasBackground();
        scwin.updateVideoLayout();
    });

    scwin.roomClient.on("adminStatus", ({ isAdmin, peerId }) => {

        scwin.isAdmin = isAdmin;
        scwin.myPeerId = peerId; // 서버가 알려준 나의 고유 ID 저장

        if (scwin.isAdmin) {
            if (scwin.uiManager.whiteboardButton) {
                scwin.uiManager.whiteboardButton.onclick = () => {
                    const activate = !scwin.isWhiteboardActive;
                    wsInstance.send(JSON.stringify({ action: "canvas", data: { type: activate ? "activate" : "deactivate" } }));
                };
            };
            // 화면 공유 버튼 로직은 그대로 유지
            scwin.uiManager.enableScreenSharing(() => {
                if (scwin.isScreenSharing) scwin.roomClient.stopScreenShare();
                else scwin.roomClient.startScreenShare();
            });

            // 관리자용 AI 모니터링 대시보드 초기화만 (고정 버튼은 생성하지 않음)
            if (window.AIDashboardController) {
                window.AIDashboardController.init();
                console.log('[AI Dashboard] 관리자 대시보드 초기화 완료 (모듈 버튼으로만 사용)');
            }
        } else {
            // 일반 사용자용
            if (scwin.uiManager && scwin.uiManager.hideWhiteboardButton) {
                scwin.uiManager.hideWhiteboardButton();
            }
            if (scwin.uiManager && scwin.uiManager.disableScreenSharing) {
                scwin.uiManager.disableScreenSharing();
            }

            // 개인 대시보드 초기화만 (고정 버튼은 생성하지 않음)
            // 모든 사용자에게 이미 초기화되어 있으므로 추가 처리 불필요
            console.log('[Personal Dashboard] 개인 대시보드는 모듈 버튼으로만 사용');
        }
    });

    scwin.roomClient.on("screenShareState", ({ isSharing }) => {
        scwin.isScreenSharing = isSharing;

        // 화면공유 버튼 상태 업데이트
        scwin.updateModuleButtonState('SCREEN', scwin.isScreenSharing, {
            activeText: '공유 중',
            inactiveText: '화면공유',
            activeColor: '#e74c3c',
            inactiveColor: '#667eea'
        });

        //scwin.uiManager.screenShareButton.textContent = isSharing ? "공유 중지" : "화면 공유";
        // 화면공유 시작시에만 칠판 지우기
        isSharing ? scwin.canvasModule.clear() : "";

        // 순서 변경: 배경 상태를 먼저 업데이트
        scwin.updateCanvasBackground();
        scwin.updateVideoLayout();
    });

    scwin.roomClient.on("controlsReady", () => {
        if (scwin.uiManager && scwin.uiManager.enableControls) {
            scwin.uiManager.enableControls();
        }

        if (scwin.uiManager && scwin.uiManager.cameraOffButton) {
            scwin.uiManager.cameraOffButton.onclick = () => {
                isVideoEnabled = !isVideoEnabled;
                scwin.roomClient.setVideoEnabled(isVideoEnabled);
                if (scwin.uiManager && scwin.uiManager.updateCameraButton) {
                    scwin.uiManager.updateCameraButton(isVideoEnabled);
                }
            };
        }

        if (scwin.uiManager && scwin.uiManager.muteButton) {
            scwin.uiManager.muteButton.onclick = () => {
                isAudioEnabled = !isAudioEnabled;
                scwin.roomClient.setAudioEnabled(isAudioEnabled);
                if (scwin.uiManager && scwin.uiManager.updateMuteButton) {
                    scwin.uiManager.updateMuteButton(isAudioEnabled);
                }
            };
        }

        // 대시보드 컨트롤러들은 이미 초기화되어 있으므로 추가 버튼 생성 불필요
        // 모든 대시보드 기능은 모듈 버튼을 통해서만 사용


        // ------------------------대기방 설정값 강제 적용----------------------------
        setTimeout(() => {
            scwin.roomClient.setVideoEnabled(!scwin.isCameraOff);
            scwin.roomClient.setAudioEnabled(!scwin.isMicMuted);

            // UI 버튼 상태도 동기화
            if (scwin.uiManager.updateCameraButton) {
                scwin.uiManager.updateCameraButton(!scwin.isCameraOff);
            }
            if (scwin.uiManager.updateMuteButton) {
                scwin.uiManager.updateMuteButton(!scwin.isMicMuted);
            }
        }, 500); // 0.5초 지연으로 확실히 적용
    });

    // RoomClient에서 로컬 비디오 상태 변경 이벤트를 수신하여 UIManager에 전달
    scwin.roomClient.on("localVideoStateChanged", (isEnabled) => {
        const myPeer = scwin.remotePeers.get(scwin.myPeerId);
        if (myPeer && myPeer.elementWrapper) {
            myPeer.elementWrapper.classList.toggle('video-paused', !isEnabled);
        }
    });

    // 여기서 video element 요소들만 남겨놓고 aimodule 로직은 따로 분리 -> scwin.loadAIModule
    // 보유한 모듈만 로드되는 거를 처리하기 위해서...
    // 로드 순서 : onpageload 시작 -> roonClient.join() 호출 -> localstreamready 발생(여기서 hasmodule값=false)
    //     -> 1초후 loadsessionmodules() 실행 -> 그 뒤에 true로 바뀌어버림.
    // ===> 따로 빼서 creamodulebuttons할때 다시 로드시켜줘야함
    scwin.roomClient.on("localStreamReady", (videoElement) => {
        if (!scwin.myPeerId) {
            console.error("My Peer ID is not set yet!");
            return;
        }

        const elementWrapper = document.createElement('div');
        elementWrapper.id = `peer-container-${scwin.myPeerId}`; // ID 명확화
        elementWrapper.style.height = '725px';


        // WebSquare 영역에 직접 삽입되도록 보장
        //const videoContainer = document.getElementById('mf_grp_video_area');

        scwin.uiManager.createMainContent();
        //scwin.uiManager.initializeUI();

        // if (videoContainer && elementWrapper) {
        //     // 라벨 뒤에 배치되도록 z-index 설정
        //     elementWrapper.style.zIndex = '2';
        //     elementWrapper.style.position = 'absolute';
        //     elementWrapper.style.top = '0';
        //     elementWrapper.style.left = '0';
        //     elementWrapper.style.width = '100%';
        //     elementWrapper.style.height = '100%';
        // }

        // const sidebarArea = document.getElementById('mf_group8');
        // if (sidebarArea) {
        //     sidebarArea.style.cssText = `
        // display: flex;
        // flex-direction: column;
        // gap: 8px;
        // padding: 8px;
        // overflow-y: auto;
        // height: 100%;
        // `;
        // }

        // 윈도우 리사이즈 이벤트에 추가
        window.addEventListener('resize', () => {
            const videoElements = document.querySelectorAll('#mf_grp_video_area video');
            videoElements.forEach(video => {
                // 비디오 크기 재조정 로직
                video.style.objectFit = 'cover';
            });
        });

        // AI 렌더링을 위한 캔버스 생성
        const canvasEl = document.createElement("canvas");
        canvasEl.style.cssText = "position: absolute; top: 0; left: 0; width: 100%; height: 100%; pointer-events: none;";

        elementWrapper.appendChild(videoElement);
        elementWrapper.appendChild(canvasEl);

        scwin.videoElement = videoElement;
        scwin.canvasEl = canvasEl;

        // UIManager에 로컬 비디오와 캔버스 요소 전달
        scwin.uiManager.setLocalMediaElements(videoElement, canvasEl);

        // 자기 자신을 remotePeers 맵에 추가
        const localUserName = meetingSettings.get("participantName");
        const truncatedLocalUserName = localUserName.length > 5 ? localUserName.substring(0, 5) + '...' : localUserName;
        elementWrapper.setAttribute('data-username', truncatedLocalUserName);

        scwin.remotePeers.set(scwin.myPeerId, {
            videoProducerId: null, // 나중에 채워짐
            audioProducerId: null, // 나중에 채워짐
            elementWrapper: elementWrapper,
            isLocal: true // 로컬 사용자임을 표시
        });

        // 대기방이 숨겨진 후 설정값 적용
        // setTimeout(function () {
        //     scwin.applyWaitingRoomSettings();
        // }, 100);

        scwin.updateVideoLayout();

        // --------------------비디오 스트림이 준비된 후 AI 모듈 조건 재체크---------------------------
        if (scwin.userHasAiModule && scwin.videoElement && scwin.canvasEl) {
            console.log("localStreamReady에서 지연된 AI 모듈 로딩 시작");
            scwin.loadAIModule();
        }
    });
    // 로컬 프로듀서 생성 시 producerId 업데이트
    scwin.roomClient.on('producer-created', ({ kind, producerId }) => {
        const myPeer = scwin.remotePeers.get(scwin.myPeerId);
        if (myPeer) {
            if (kind === 'video') myPeer.videoProducerId = producerId;
            if (kind === 'audio') myPeer.audioProducerId = producerId;
        }
    });

    scwin.loadAIModule = function () {
        try {
            if (!scwin.isAdmin) {
                scwin.loadModule(
                    "/InsWebApp/media/dist/modules/mediapipe.bundle.js",
                    "MediaPipeModule"
                ).then(MediaPipeModule => {
                    if (MediaPipeModule && !MediaPipeModule.prototype) {
                        MediaPipeModule = MediaPipeModule.MediaPipeModule || MediaPipeModule.default;
                    }
                    aiModule = new MediaPipeModule(scwin.videoElement, MEDIA_PIPE_WORKER_URL);
                    console.log("AI Module will be initialized.");

                    if (aiModule) aiModule.start();

                    aiModule.on("landmarksUpdate", (landmarks) => {
                        scwin.uiManager.drawFaceMesh(landmarks);
                    });


                    aiModule.on("drowsinessDetected", (data) => {
                        if (!scwin.isAdmin) {
                            console.log("Event: drowsinessUpdate -> Sending status to server.");
                            scwin.createPopUp("drowsinessPopUp", "Warning !!", null, "/InsWebApp/ui/media_pipe_pop_up/drowsiness_pop_up.xml", 400, 425);
                            scwin.roomClient.sendPeerStatus(data);

                            // 개인 대시보드에 직접 알림
                            if (window.PersonalDashboardController) {
                                window.PersonalDashboardController.handleDrowsinessDetected();
                            }
                        }
                    });
                    aiModule.on("drowsinessResolved", (data) => {
                        console.log("Event: drowsinessUpdate -> Sending status to server.");
                        scwin.roomClient.sendPeerStatus(data);

                        // 개인 대시보드에 직접 알림
                        if (window.PersonalDashboardController) {
                            window.PersonalDashboardController.handleDrowsinessResolved();
                        }
                    });

                    aiModule.on("absenceStarted", (data) => {
                        console.log(" Event: absenceStarted -> Sending status to server.");
                        scwin.createPopUp("adfPopUp", "Warning !!", null, "/InsWebApp/ui/media_pipe_pop_up/afd_pop_up.xml", 400, 475);
                        scwin.roomClient.sendPeerStatus(data);

                        // 개인 대시보드에 직접 알림
                        if (window.PersonalDashboardController) {
                            window.PersonalDashboardController.handleAbsenceDetected();
                        }
                    });
                    aiModule.on("absenceEnded", (data) => {
                        console.log(" Event: absenceEnded -> Sending status to server.");
                        scwin.roomClient.sendPeerStatus(data);

                        // 개인 대시보드에 직접 알림
                        if (window.PersonalDashboardController) {
                            window.PersonalDashboardController.handleAbsenceResolved();
                        }
                    });

                    aiModule.on("error", (error) => {
                        console.error(" AI Module Error:", error);
                    });
                });
            }
        } catch (error) {
            console.error("Failed to load MediaPipeModule:", error);
        }
    }

    scwin.roomClient.on("new-consumer", async (consumer) => {
        const { track, producerId, appData } = consumer;
        const peerId = appData.peerId;
        if (!peerId) return;

        let peer = scwin.remotePeers.get(peerId);
        if (!peer) {
            // 화면 공유 속성 추가
            peer = {
                videoProducerId: null,
                audioProducerId: null,
                screenShareProducerId: null, // 추가
                elementWrapper: null,
                audioElement: null,
                screenShareElement: null, // 추가
                isScreenShare: false,
                isLocal: false // 원격 사용자
            };
            scwin.remotePeers.set(peerId, peer);

            // AI 통계 시스템에 새 참여자 초기화
            if (window.aiMonitoringStats) {
                const peerName = `참여자_${peerId.slice(-4)}`;
                window.aiMonitoringStats.initializeParticipant(peerId, peerName);
                console.log('[AI Stats] 새 참여자 초기화:', peerId, peerName);
            }
        }

        if (appData && appData.source === 'screen') {
            peer.isScreenShare = true;
            // 카메라와 분리된 전용 속성에 ID 저장
            peer.screenShareProducerId = producerId;

            const elementWrapper = document.createElement("div");
            elementWrapper.id = `remote-screen-${producerId}`;
            const videoEl = document.createElement(track.kind);
            videoEl.srcObject = new MediaStream([track]);
            videoEl.autoplay = true;
            videoEl.playsInline = true;
            elementWrapper.appendChild(videoEl);

            // 전용 속성에 DOM 요소 저장
            peer.screenShareElement = elementWrapper;

            if (peerId === scwin.myPeerId) {
                // 관리자의 경우 localScreenShareElement도 세팅 (필요 시)
                scwin.localScreenShareElement = elementWrapper;
            }
            scwin.updateCanvasBackground();
        } else if (track.kind === 'video') {
            peer.videoProducerId = producerId;

            if (!peer.elementWrapper) {
                const elementWrapper = document.createElement('div');
                elementWrapper.id = `remote-peer-${peerId}`;
                elementWrapper.onclick = () => {
                    if (scwin.isScreenSharing || scwin.isWhiteboardActive) {
                        alert("화면 공유 또는 칠판이 활성화된 중에는 다른 화면을 고정할 수 없습니다.");
                        return;
                    }
                    scwin.pinnedProducerId = (scwin.pinnedProducerId === peer.videoProducerId) ? null : peer.videoProducerId;
                    scwin.updateVideoLayout();
                };
                peer.elementWrapper = elementWrapper;
            }

            const videoEl = document.createElement('video');
            videoEl.srcObject = new MediaStream([track]);
            videoEl.autoplay = true;
            videoEl.playsInline = true;
            peer.elementWrapper.appendChild(videoEl);

        } else if (track.kind === 'audio') {
            peer.audioProducerId = producerId;
            const audioEl = document.createElement('audio');
            audioEl.id = `remote-audio-${producerId}`;
            audioEl.srcObject = new MediaStream([track]);
            audioEl.autoplay = true;
            document.body.appendChild(audioEl);
            peer.audioElement = audioEl;
        }
        scwin.updateVideoLayout();
    });

    scwin.roomClient.on("producer-closed", ({ producerId, isScreenShareProducer, isLocalVideoProducer, peerId }) => {
        if (peerId) {
            const peer = scwin.remotePeers.get(peerId);
            if (peer) {
                // 화면 공유 스트림 종료 처리
                if (peer.screenShareProducerId === producerId) {
                    if (peer.screenShareElement) {
                        peer.screenShareElement.remove();
                        peer.screenShareElement = null;
                    }
                    peer.screenShareProducerId = null;
                    peer.isScreenShare = false; // 상태 플래그도 초기화
                }
                // 카메라 스트림 종료 처리 (기존 로직 유지)
                if (peer.videoProducerId === producerId) {
                    if (peer.elementWrapper) {
                        peer.elementWrapper.remove();
                        peer.elementWrapper = null;
                    }
                    peer.videoProducerId = null;
                }
                // 오디오 처리 로직
                if (peer.audioProducerId === producerId) {
                    if (peer.audioElement) {
                        peer.audioElement.remove();
                        peer.audioElement = null;
                    }
                    peer.audioProducerId = null;
                }

                // 참여자의 모든 스트림이 종료되었을 때 완전히 제거
                if (!peer.videoProducerId && !peer.audioProducerId && !peer.screenShareProducerId) {
                    scwin.remotePeers.delete(peerId);

                    // AI 통계 시스템에서도 참여자 제거는 하지 않음 (통계 유지를 위해)
                    // 대신 마지막 상태를 자리비움으로 설정
                    if (window.aiMonitoringStats) {
                        window.aiMonitoringStats.updateParticipantStatus(peerId, { isPresent: false });
                        console.log('[AI Stats] 참여자 연결 종료:', peerId);
                    }
                }
            }
        }

        if (isScreenShareProducer) {
            // 로컬 화면 공유가 닫혔을 때 처리
            if (scwin.localScreenShareElement && isLocalVideoProducer) { // isLocalVideoProducer는 로컬 비디오 프로듀서가 닫혔을 때 true
                scwin.localScreenShareElement.remove();
                scwin.localScreenShareElement = null;
            }
            scwin.updateCanvasBackground();
        }

        if (scwin.pinnedProducerId === producerId) {
            scwin.pinnedProducerId = null;
        }
        scwin.updateVideoLayout();
    });

    scwin.roomClient.on("local-screen-share-started", (track) => {
        const screenShareWrapper = document.createElement("div");
        screenShareWrapper.id = "local-screen-share-wrapper";
        const element = document.createElement(track.kind);
        element.srcObject = new MediaStream([track]);
        element.muted = true;
        element.autoplay = true;
        element.playsInline = true;
        screenShareWrapper.appendChild(element);

        scwin.localScreenShareElement = screenShareWrapper;

        scwin.updateCanvasBackground();
        scwin.updateVideoLayout();
    });

    scwin.roomClient.on("local-screen-share-stopped", () => {
        if (scwin.localScreenShareElement) {
            scwin.localScreenShareElement.remove();
            scwin.localScreenShareElement = null;
        }
        scwin.updateVideoLayout();
    });

    // --- 원격 사용자의 비디오/오디오 상태 변경 처리 ---
    scwin.roomClient.on("remote-producer-pause", ({ producerId, userName }) => {
        for (const peer of scwin.remotePeers.values()) {
            if (peer.videoProducerId === producerId) {
                const truncatedUserName = userName.length > 5 ? userName.substring(0, 5) + '...' : userName;
                console.log("현재 이름은,,", truncatedUserName)
                scwin.uiManager.updateRemoteVideoStatus(peer.elementWrapper, true, truncatedUserName);
                break;
            }
        }
    });

    scwin.roomClient.on("remote-producer-resume", ({ producerId }) => {
        for (const peer of scwin.remotePeers.values()) {
            if (peer.videoProducerId === producerId) {
                scwin.uiManager.updateRemoteVideoStatus(peer.elementWrapper, false);
                break;
            }
        }
    });

    scwin.roomClient.on("remote-audio-pause", ({ producerId }) => {
        for (const peer of scwin.remotePeers.values()) {
            if (peer.audioProducerId === producerId) {
                scwin.uiManager.updateRemoteAudioStatus(peer.elementWrapper, true);
                break;
            }
        }
    });

    scwin.roomClient.on("remote-audio-resume", ({ producerId }) => {
        for (const peer of scwin.remotePeers.values()) {
            if (peer.audioProducerId === producerId) {
                scwin.uiManager.updateRemoteAudioStatus(peer.elementWrapper, false);
                break;
            }
        }
    });

    // 1. URL 파라미터에서 sessionId 먼저 확인
    sessionId = $p.getParameter("sessionId");
    console.log('URL 파라미터 sessionId:', sessionId);

    // 2. URL 파라미터가 없으면 localStorage에서 확인 (세션 생성자용)
    if (!sessionId) {
        sessionId = localStorage.getItem('currentSessionId');
        console.log('localStorage sessionId:', sessionId);
    }

    // 3. sessionId가 있으면 currentSessionId에 저장하고 모듈 로드
    if (sessionId) {
        scwin.currentSessionId = sessionId;
        console.log('현재 sessionId 설정:', scwin.currentSessionId);

        // // 대기방에 sessionId 전달
        // setTimeout(() => {
        //     scwin.notifyWaitingRoomOfSessionId();
        // }, 100);

        // 페이지 로드 완료 후 모듈 로드
        setTimeout(function () {
            scwin.loadSessionModules(sessionId);
        }, 1000);
    } else {
        console.log("세션 정보를 찾을 수 없습니다.");
    }

    // 로컬 사용자를 AI 통계 시스템에 초기화
    if (window.aiMonitoringStats) {
        // roomClient.join() 후 peerId가 설정되기를 기다림
        setTimeout(() => {
            const localPeerId = scwin.roomClient.peerId || 'local-user';
            scwin.myPeerId = localPeerId; // 전역 변수에 저장
            window.aiMonitoringStats.initializeParticipant(localPeerId, '관리자(나)');
            console.log('[AI Stats] 로컬 사용자 초기화:', localPeerId);
        }, 1000);
    }

    // 하단 모듈 영역 레이아웃 조정 함수
    scwin.adjustBottomModulesLayout = function () {
        var bottomModulesContainer = document.getElementById('group11');
        if (!bottomModulesContainer) return;

        var visibleModules = 0;

        // 표시된 모듈 개수 세기 (module-area-visible 클래스가 있는 것들)
        for (var i = 12; i <= 26; i++) {
            var areaElement = document.getElementById('group' + i);
            if (areaElement && areaElement.classList.contains('module-area-visible')) {
                visibleModules++;
            }
        }

        console.log('표시된 모듈 개수:', visibleModules);

        // 모듈이 없으면 하단 영역 자체를 숨김
        if (visibleModules === 0) {
            bottomModulesContainer.style.display = 'none';

            // 메인 비디오 영역 높이를 늘려서 하단 공간을 채움
            var videoArea = document.getElementById('mf_grp_video_area');
            if (videoArea) {
                videoArea.style.height = '800px';
            }
        } else {
            bottomModulesContainer.style.display = 'flex';

            // 메인 비디오 영역 높이를 원래대로 복구
            var videoArea = document.getElementById('mf_grp_video_area');
            if (videoArea) {
                videoArea.style.height = '720px';
            }
        }
    };

    // 테스트용 상태 업데이트 함수
    window.testAIStatus = function () {
        if (!window.aiMonitoringStats) {
            console.log('AI 통계 시스템이 없습니다.');
            return;
        }

        const localUserId = scwin.myPeerId || 'local-user';
        console.log('테스트용 AI 상태 업데이트:', localUserId);

        // 자리비움 상태 시뮬레이션
        window.aiMonitoringStats.updateParticipantStatus(localUserId, { isPresent: false });

        setTimeout(() => {
            window.aiMonitoringStats.updateParticipantStatus(localUserId, { isPresent: true });
        }, 2000);

        setTimeout(() => {
            window.aiMonitoringStats.updateParticipantStatus(localUserId, { isDrowsy: true });
        }, 4000);

        setTimeout(() => {
            window.aiMonitoringStats.updateParticipantStatus(localUserId, { isDrowsy: false });
        }, 6000);
    };


};

//------------------------모듈 배치 스크립트--------------------//

// 모듈 데이터 로드 함수
scwin.loadSessionModules = function (sessionId) {
    console.log("세션 모듈 로드 시작:", sessionId);
    dma_sessionRequest.set("sessionId", sessionId);
    $p.executeSubmission("sbm_getSessionModuleDetails");
};

// 서브미션 성공 콜백
scwin.sbm_getSessionModuleDetails_submitdone = function (e) {
    console.log("서브미션 성공:", e);

    if (e && e.responseJSON && e.responseJSON.elData) {
        var sessionModuleList = e.responseJSON.elData.sessionModuleDetailVoList;

        if (sessionModuleList && sessionModuleList.length > 0) {
            console.log("받은 모듈 데이터:", sessionModuleList);
            scwin.createModuleButtons(sessionModuleList);
        } else {
            console.log("사용 가능한 모듈이 없습니다. 대체 버튼을 생성합니다.");
        }
    } else {
        console.log("응답 데이터가 올바르지 않습니다. 대체 버튼을 생성합니다.");
    }
};

// 서브미션 실패 콜백
scwin.sbm_getSessionModuleDetails_submiterror = function (e) {
    console.error("모듈 목록 로드 실패:", e);
    alert("모듈 목록을 불러오는데 실패했습니다. 예시 버튼을 표시합니다.");
};

// 영역 ID 매핑 함수 (완전히 교체)
scwin.mapAreaId = function (originalAreaId) {
    console.log("원본 영역 ID:", originalAreaId);

    // 다양한 형태의 ID 처리
    var areaNumber = null;

    // area id가 mf_contentFrame_fr_session_making_process_grp_areaXX 형태
    if (originalAreaId.includes('grp_area')) {
        var match = originalAreaId.match(/grp_area(\d+)/);
        if (match) {
            areaNumber = parseInt(match[1]);
        }
    }

    console.log("추출된 영역 번호:", areaNumber);

    // session_room3.xml의 실제 ID로 매핑
    if (areaNumber && areaNumber >= 3 && areaNumber <= 14) {
        var mappedId = 'mf_group' + (areaNumber + 9);
        console.log("매핑된 ID:", originalAreaId, "->", mappedId);
        return mappedId;
    }

    console.log("매핑 실패, 원본 ID 반환:", originalAreaId);
    return originalAreaId;
};

// 서버에서 받은 데이터로 모듈 버튼 생성
scwin.createModuleButtons = function (sessionModules) {
    console.log("모듈 버튼 생성 시작:", sessionModules);

    scwin.clearAllButtonAreas();

    sessionModules.forEach(function (sessionModule) {
        try {
            var config = JSON.parse(sessionModule.sessionModuleConfig);
            var originalAreaId = config.area;
            var mappedAreaId = scwin.mapAreaId(originalAreaId);

            console.log("모듈 처리:", sessionModule.name, "원본:", originalAreaId, "매핑:", mappedAreaId);

            var moduleInfo = {
                moduleId: sessionModule.moduleId,
                code: sessionModule.code,
                name: sessionModule.name,
                description: sessionModule.description,
                icon: sessionModule.icon,
                type: scwin.getModuleType(sessionModule.code)
            };
            // 버튼 생성할때 세션 모듈 리스트에 있는 모듈의 userHas 변수를 true로 설정
            scwin.activateUserHasModule(moduleInfo.code);

            scwin.createModuleButton(mappedAreaId, moduleInfo);
        } catch (e) {
            console.error("모듈 생성 실패:", sessionModule.name, e);
        }
    });

    console.log("모듈 버튼 생성 완료");

    //---> 여기서 AI 모듈이 활성화되었고 비디오 스트림이 준비되었으면 AI 모듈 로드
    if (scwin.userHasAiModule && scwin.videoElement && scwin.canvasEl) {
        console.log("지연된 AI 모듈 로딩 시작");
        console.log("AI 모듈 로딩 조건 체크:");
        console.log("scwin.userHasAiModule:", scwin.userHasAiModule);
        console.log("scwin.videoElement:", scwin.videoElement);
        console.log("scwin.canvasEl:", scwin.canvasEl);
        scwin.loadAIModule();
    }
};

scwin.activateUserHasModule = function (moduleCode) {
    switch (moduleCode) {
        case 'FACEAI':
            scwin.userHasAiModule = true;
            break;
        case 'CHAT':
            scwin.userHasChatModule = true;
            break;
        case 'WHITEBOARD':
        case 'CANVAS':
            scwin.userHasCanvasModule = true;
            break;
        case 'SCREEN':
            scwin.userHasScreenShareModule = true;
            break;
    }
    console.log("모듈 활성화:", moduleCode);
};

// 모듈 타입 결정 함수
scwin.getModuleType = function (moduleCode) {
    var uiModules = ['CHAT', 'DOCUMENT', 'SIGNATURE', 'FILE', 'CALENDAR', 'SCREEN_VIEW', 'PARTICIPANTS', 'FACEAI'];
    var actionModules = ['MIC', 'CAMERA', 'SCREEN', 'RECORD'];

    if (uiModules.indexOf(moduleCode) !== -1) {
        return 'UI_MODULE';
    } else if (actionModules.indexOf(moduleCode) !== -1) {
        return 'ACTION_MODULE';
    } else {
        return 'UI_MODULE';
    }
};

